  slytherin:{name:'Sonserina',short:'Sonserina',eyebrow:'GRANDES DESTINOS COMEÇAM AQUI',description:'Sob o Lago Negro, a luz verde atravessa as janelas. Pedra, prata e mistério dão vida à sala comunal.',subtitle:'Um refúgio sob o Lago Negro',color:'#5b8c72'},
  ravenclaw:{name:'Corvinal',short:'Corvinal',eyebrow:'A IMAGINAÇÃO NÃO CONHECE LIMITES',description:'Janelas arqueadas, livros e um céu de estrelas. Aqui, cada pergunta abre uma nova possibilidade.',subtitle:'Livros, bronze e constelações',color:'#6087b0'},
  hufflepuff:{name:'Lufa-Lufa',short:'Lufa-Lufa',eyebrow:'HÁ MAGIA EM PERTENCER',description:'Plantas, madeira e tons de mel. Uma sala acolhedora, iluminada por janelas redondas junto ao jardim.',subtitle:'Plantas, luz dourada e aconchego',color:'#c2a14f'},
  library:{name:'A biblioteca',short:'Biblioteca',eyebrow:'CADA LIVRO É UMA NOVA PORTA',description:'Entre estantes antigas e mesas de leitura, o conhecimento espera. Procure os pontos de luz para descobrir seus segredos.',subtitle:'Estantes antigas e saberes esquecidos',color:'#b49260'}
